      font-size: 1.375rem;
      font-weight: 700;
      min-width: 72px;
    }

    .donate-amount-impact {
      font-size: 0.875rem;
      opacity: 0.85;
    }

    .btn-donate-large {
      display: block;
      width: 100%;
      padding: 16px;
      background: var(--white);
      color: var(--red);
      font-size: 1.125rem;
      font-weight: 700;
      border-radius: var(--radius);
      text-align: center;
      margin-top: 16px;
