      background: var(--gray-100);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    /* ========== DONATION MODAL ========== */
    .modal-overlay {
      display: none;
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.6);
      z-index: 200;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .modal-overlay.open {
      display: flex;
    }

    .modal {
      background: var(--white);
      border-radius: 16px;
      max-width: 520px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      box-shadow: var(--shadow-xl);
      animation: modalIn 0.3s ease;
    }

    @keyframes modalIn {
      from { opacity: 0; transform: scale(0.95) translateY(10px); }
      to { opacity: 1; transform: scale(1) translateY(0); }
    }

    .modal-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 24px 24px 0;
    }

    .modal-header h2 {
      font-family: var(--font-serif);
      font-size: 1.5rem;
      color: var(--navy);
    }

    .modal-close {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-500);
      transition: background var(--transition);
    }

    .modal-close:hover { background: var(--gray-100); }

    .modal-body {
      padding: 24px;
    }

    .modal-amounts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 16px;
    }

    .modal-amount-btn {
      padding: 16px 8px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      font-size: 1.125rem;
      font-weight: 700;
      color: var(--gray-700);
      transition: all var(--transition);
      background: var(--white);
    }

    .modal-amount-btn:hover {
      border-color: var(--red);
      color: var(--red);
    }

    .modal-amount-btn.selected {
      background: var(--red);
      border-color: var(--red);
      color: var(--white);
    }

    .modal-custom {
      margin-bottom: 20px;
    }

    .modal-custom input {
      width: 100%;
      padding: 14px 16px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      font-size: 1rem;
      font-family: var(--font-sans);
      transition: border-color var(--transition);
    }

    .modal-custom input:focus {
      outline: none;
      border-color: var(--red);
    }

    .modal-custom input::placeholder {
      color: var(--gray-400);
    }

    .modal-impact {
      background: var(--gray-50);
      border-radius: var(--radius);
      padding: 16px;
      margin-bottom: 24px;
      font-size: 0.9375rem;
      color: var(--gray-600);
      line-height: 1.5;
    }

    .modal-impact strong {
      color: var(--navy);
    }

    .btn-modal-donate {
      display: block;
      width: 100%;
      padding: 16px;
      background: var(--red);
      color: var(--white);
      font-size: 1.125rem;
      font-weight: 700;
      border-radius: var(--radius);
      text-align: center;
      transition: all var(--transition);
    }

    .btn-modal-donate:hover {
      background: var(--red-dark);
    }

    .modal-secure {
      text-align: center;
      margin-top: 12px;
      font-size: 0.8125rem;
      color: var(--gray-400);
    }

    /* ========== FOOTER ========== */
    .footer {
      background: var(--gray-900);
      color: var(--gray-300);
      padding: 64px 0 32px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      color: var(--white);
      font-size: 0.9375rem;
      font-weight: 600;
      margin-bottom: 16px;
    }

    .footer-col a {
      display: block;
      font-size: 0.875rem;
      padding: 4px 0;
      opacity: 0.7;
      transition: opacity var(--transition);
    }

    .footer-col a:hover { opacity: 1; }

    .footer-bottom {
      border-top: 1px solid var(--gray-700);
      padding-top: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-copy {
      font-size: 0.8125rem;
      opacity: 0.6;
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--gray-800);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0.7;
      transition: all var(--transition);
    }

    .footer-social a:hover {
      opacity: 1;
      background: var(--red);
    }

    .footer-social svg {
      width: 18px;
      height: 18px;
      fill: var(--gray-300);
    }

    /* ========== RESPONSIVE ========== */
    @media (max-width: 1024px) {
      .hero .container {
        grid-template-columns: 1fr;
        gap: 40px;
      }
      .hero-text h1 { font-size: 2.5rem; }
      .hero-image { display: none; }
      .impact .container { grid-template-columns: repeat(2, 1fr); }
      .involved-grid { grid-template-columns: repeat(2, 1fr); }
      .donate-cta-inner { grid-template-columns: 1fr; }
    }

    @media (max-width: 768px) {
      .nav-desktop { display: none; }
      .hamburger { display: flex; }
      .mobile-nav { display: block; }
      .mobile-overlay { display: block; pointer-events: none; }
      .mobile-overlay.visible { pointer-events: auto; }
      .header-top { display: none; }
      .hero { padding: 48px 0; }
      .hero-text h1 { font-size: 2rem; }
      .stat-number { font-size: 2.25rem; }
      .involved-grid { grid-template-columns: 1fr; }
      .news-card { flex: 0 0 100%; }
      .donate-cta-inner { padding: 36px 24px; }
